import{_ as a,o as n,c as h,a3 as e}from"./chunks/framework.Q4yG9rk_.js";const z=JSON.parse('{"title":"中庸","description":"儒家四书之一：天命之谓性、致中和、诚，心性与天道的精微处。","frontmatter":{"title":"中庸","description":"儒家四书之一：天命之谓性、致中和、诚，心性与天道的精微处。","category":"guide","aliases":["中庸","中庸章句","zhongyong","中庸篇章","中庸目录"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/index.md","filePath":"lizhimingde/sishu-wujing/zhongyong/index.md","lastUpdated":1790068742000}'),o={name:"lizhimingde/sishu-wujing/zhongyong/index.md"};function l(g,i,r,s,t,u){return n(),h("div",null,[...i[0]||(i[0]=[e('<h1 id="中庸" tabindex="-1">中庸 <a class="header-anchor" href="#中庸" aria-label="Permalink to &quot;中庸&quot;">​</a></h1><p>《中庸》原是《礼记》第三十一篇，朱熹抽出单独成书。它比《大学》深，也难得多——<strong>《大学》讲的是路怎么走，《中庸》讲的是这条路通向的心性与天道</strong>。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>朱熹分《中庸》为<strong>三十三章</strong>：</p><ul><li><strong>首章立纲</strong>：「天命之谓性，率性之谓道，修道之谓教」——性、道、教三层一次说尽；继以「戒慎恐惧」「慎独」，再落到「致中和，天地位焉，万物育焉」。</li><li><strong>中段展开</strong>：论中庸之难（「民鲜能久矣」）、论强、论素隐行怪、论鬼神、论诚（「诚者天之道也，诚之者人之道也」）。</li><li><strong>末章收束</strong>：「上天之载，无声无臭」——由人德上达天德。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>它给中国思想补上了「内在性」的一维</strong>：天命不在外，就在人的性中。</li><li><strong>「诚」是它的核心枢纽</strong>：从「诚身」到「诚物」，从成己到成物，形成了儒家沟通天人的一套说法。</li><li><strong>「中和」成了后世心性工夫的通用语汇</strong>：喜怒哀乐之未发谓之中，发而皆中节谓之和。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读<strong>首章</strong>，三句话记牢：性—道—教；戒慎恐惧与慎独；致中和；</li><li>再看「诚」的几章（第二十至二十六章一带），这是全篇理论最深的地方；</li><li>遇「中庸」二字要小心：它<strong>不是折中、不是和稀泥</strong>，而是「无过不及」的恰当与恒常。</li><li>可与《大学》对读：《大学》由外而内（格致诚正修齐治平），《中庸》由内而外（性—道—教—天）。</li></ol><h2 id="篇章" tabindex="-1">篇章 <a class="header-anchor" href="#篇章" aria-label="Permalink to &quot;篇章&quot;">​</a></h2><p>一章一页，共 <strong>33 页</strong>。</p><ol><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-01">第1章 · 天命之谓性</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-02">第2章 · 君子中庸</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-03">第3章 · 中庸其至矣乎</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-04">第4章 · 道之不行也</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-05">第5章 · 道其不行矣夫</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-06">第6章 · 舜其大知也与</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-07">第7章 · 人皆曰予知</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-08">第8章 · 回之为人也</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-09">第9章 · 天下国家可均也</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-10">第10章 · 子路问强</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-11">第11章 · 素隐行怪</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-12">第12章 · 君子之道费而隐</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-13">第13章 · 道不远人</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-14">第14章 · 君子素其位而行</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-15">第15章 · 行远自迩</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-16">第16章 · 鬼神之为德</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-17">第17章 · 舜其大孝也与</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-18">第18章 · 无忧者其惟文王乎</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-19">第19章 · 武王周公其达孝矣乎</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-20">第20章 · 哀公问政</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-21">第21章 · 自诚明谓之性</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-22">第22章 · 唯天下至诚</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-23">第23章 · 其次致曲</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-24">第24章 · 至诚之道</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-25">第25章 · 诚者自成也</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-26">第26章 · 至诚无息</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-27">第27章 · 大哉圣人之道</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-28">第28章 · 愚而好自用</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-29">第29章 · 王天下有三重焉</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-30">第30章 · 仲尼祖述尧舜</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-31">第31章 · 唯天下至圣</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-32">第32章 · 唯天下至诚为能经纶</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-33">第33章 · 衣锦尚絅</a></li></ol><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li><strong>全 33 章已整理完成</strong>（原文单竹简分节 + 生词点查 + 白话译文 + 三问解读 + 现代重述 + 我的理解留白），原文与朱熹《四书章句集注·中庸章句》逐章核对。</li><li>章题为通行归纳（取每章首句关键词），与侧边栏同源：<code>src/.vitepress/data/zhongyong-chapters.mjs</code>。</li><li>整理方式与《道德经》一致：<strong>一章一页</strong>，目录与文件一一对应。</li><li>参考：朱熹《四书章句集注·中庸章句》</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',16)])])}const c=a(o,[["render",l]]);export{z as __pageData,c as default};
